    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long total = 0, run = 0;
    for (long long i = 2; i < n; i++) {
        if (a[i] - a[i - 1] == a[i - 1] - a[i - 2]) {
            run++;
            total += run;
        } else {
            run = 0;
        }
    }
    cout << total << "\n";

    return 0;
